def main() -> None:
    template = os.environ["TEMPLATE_DOC"]
    output_doc = os.environ["OUTPUT_DOC"]
    doc = Document(template)
    clear_document(doc)

    if "Normal" in doc.styles:
        doc.styles["Normal"].font.name = "SimSun"
        doc.styles["Normal"].font.size = Pt(12)

    add_text_paragraph(doc, TITLE, bold=True, center=True)
    for claim in CLAIMS:
        add_text_paragraph(doc, claim)
        if claim.startswith("3."):
            add_math_paragraph(doc, "R_req=d(p,s)+d(s,e)+d(e,p)")
            add_text_paragraph(doc, RREQ_EXPLAIN)
        if claim.startswith("4."):
            add_math_paragraph(doc, "C=w_t T+w_u E_u+w_a E_a+w_c E_c+w_w P_w+w_o P_o+w_f P_f")
            add_text_paragraph(doc, COST_EXPLAIN)

    doc.save(output_doc)
    print(output_doc)


if __name__ == "__main__":
    main()
